// ---- host logic: examples/api_tours/popups_input/host.cpp ----
// API tour (C++ Wrapper): popups, toasts and input pickers. Same page, checks and case as
// examples/c/ports/kui_api_popups_input.c (and the Go / Rust ports): at start-up the host shows and
// dismisses toasts (ToastManager), tooltips and context menus (PopupManager), reads the popup
// layer's state back after each step, configures the tooltip theme / delay and the default context
// menu (EventDispatcher), and drives the <input> picker panel (InputPicker: open, page, time,
// colour, commit, close, enable) checking the picker state and the input's value (read with the
// script engine). #tour-result ends as "PASS n/n"; the panel buttons repeat the calls with a
// visible effect.
//
// Wrapper differences handled here (the checks compare the equivalent Wrapper result):
//   * Failing setters throw kui::Error; status() is the C status (INVALID_ARG checks).
//   * PopupManager::showContextMenu returns 0 for an empty item list without calling the C ABI
//     (the C version gets KUI_ERR_INVALID_ARG); menu item ids are the item indices and each item
//     has its own callback. The C release_fn has no Wrapper counterpart: the tour counts when the
//     menu's callbacks (and what they capture) are destroyed, which the Wrapper does from the C
//     release_fn.
//   * InputPicker::targetInput() returns nullptr where the C call returns KUI_ERR_NOT_FOUND.
// Gaps:
//   * InputPicker::open / openTime / ... return whether a picker opened, not the C status: where the
//     status itself is checked or shown (refusals, the date / toggle buttons) the tour also calls
//     kui_element_open_input_picker on element->cHandle().
//   * Element::value() reads the "value" content attribute (like kui_element_get_attribute), not
//     the input's current value: the value is read with the script engine (.value), as in C.

#include <cmath>
#include <cstdarg>
#include <functional>
#include <memory>
#include <sstream>
#include <vector>

namespace {

kui::Document* g_doc = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------

int g_total = 0;
int g_failed = 0;
int g_known = 0;
std::string g_failed_names;

std::string fmt(const char* format, ...) {
    char buffer[512];
    va_list args;
    va_start(args, format);
    std::vsnprintf(buffer, sizeof buffer, format, args);
    va_end(args);
    return buffer;
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

// A documented behaviour the engine currently gets wrong: logged, not counted.
void known(const std::string& name, bool ok, const std::string& bug, const std::string& detail) {
    if (ok) {
        g_total++;
        log_row(name, "ok", "ok");
        return;
    }
    g_known++;
    std::fprintf(stderr, "tour known bug: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "known", "KNOWN BUG: " + bug + " (" + detail + ")");
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? fmt("PASS %d/%d", g_total, g_total)
                                     : fmt("FAIL %d/%d: ", g_failed, g_total) + g_failed_names;
    if (g_known) text += fmt(" (known bugs: %d)", g_known);
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", std::to_string(g_known));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(std::string(group) + ".exception", false, error.what());
    }
}

// Status of a Wrapper call: KUI_OK, or the status of the kui::Error it throws.
KuiStatus status_of(const std::function<void()>& call) {
    try {
        call();
        return KUI_OK;
    } catch (const kui::Error& error) {
        return error.status();
    }
}

// ---- Small helpers ----------------------------------------------------------------------

kui::PopupManager& popups() { return g_doc->popupManager(); }
kui::InputPicker& picker() { return g_doc->inputPicker(); }
kui::ToastManager& toasts() { return g_doc->toastManager(); }

bool near_f(double a, double b, double tolerance) { return std::fabs(a - b) <= tolerance; }

kui::Element* by_id(const char* id) { return g_doc->getElementById(id); }

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = by_id(id)) element->setTextContent(text);
}

kui::Rect rect_of(const char* id) {
    kui::Element* element = by_id(id);
    return element ? element->boundingClientRect() : kui::Rect{};
}

int has_type(kui::PopupType type) { return popups().hasPopupOfType(type) ? 1 : 0; }
int any_popup() { return popups().hasActivePopups() ? 1 : 0; }
int toast_count() { return toasts().count(); }

// The input's current value (Element::value() reads only the content attribute).
std::string input_value(const char* id) {
    if (!tour_script) return std::string();
    std::ostringstream code;
    code << "return document:getElementById('" << id << "').value";
    const kui::ScriptResult result = tour_script->eval(code.str());
    return result.success ? result.value.asString() : std::string();
}

const char* status_name(KuiStatus status) {
    switch (status) {
        case KUI_OK: return "OK";
        case KUI_ERR_INVALID_ARG: return "INVALID_ARG";
        case KUI_ERR_NOT_FOUND: return "NOT_FOUND";
        case KUI_ERR_NOT_SUPPORTED: return "NOT_SUPPORTED";
        default: return "ERROR";
    }
}

const char* mode_name(kui::PickerMode mode) {
    switch (mode) {
        case kui::PickerMode::Date: return "date";
        case kui::PickerMode::Time: return "time";
        case kui::PickerMode::DateTimeLocal: return "datetime-local";
        case kui::PickerMode::Color: return "color";
        default: return "none";
    }
}

std::string hex_rgb(const kui::Color& color) {
    return fmt("%02x%02x%02x", color.r, color.g, color.b);
}

// ---- Toasts: show two, dismiss one by id, then all; the count is read back -------------

kui::u32 g_toast_ids[2];
int g_toast_base = 0;

kui::u32 show_toast(const std::string& message, kui::ToastLevel level, int duration_ms) {
    kui::ToastConfig config;
    config.message = message;
    config.title = "KUI API tour";
    config.level = level;
    config.durationMs = duration_ms;
    config.closable = true;
    return toasts().show(config);
}

void check_toasts() {
    g_toast_base = toast_count();
    g_toast_ids[0] = show_toast("First toast (stays until dismissed)", kui::ToastLevel::Info, 0);
    g_toast_ids[1] = show_toast("Second toast", kui::ToastLevel::Success, 0);
    const int after_show = toast_count();
    check("toast.get_toast_count", g_toast_base >= 0 && after_show == g_toast_base + 2 &&
              g_toast_ids[0] && g_toast_ids[1] && g_toast_ids[0] != g_toast_ids[1],
          fmt("count %d -> %d, ids %u %u", g_toast_base, after_show, g_toast_ids[0], g_toast_ids[1]));
    KuiStatus status = status_of([] { toasts().dismiss(g_toast_ids[0]); });
    check("toast.dismiss_toast", status == KUI_OK, fmt("status %d", status));
    status = status_of([] { toasts().dismissAll(); });
    check("toast.dismiss_all_toasts", status == KUI_OK, fmt("status %d", status));
    // Dismissed toasts play an exit animation and still count; the final phase checks 0.
}

// ---- Tooltip: delay and theme read back, a tooltip shown at an element's rect ----------

bool themes_equal(const kui::TooltipTheme& a, const kui::TooltipTheme& b) {
    return a.bg == b.bg && a.fg == b.fg && a.border == b.border && near_f(a.radius, b.radius, 0.01);
}

kui::TooltipTheme purple_theme() {
    kui::TooltipTheme theme;
    theme.bg = kui::Color(0x7c, 0x3a, 0xed, 0xff);
    theme.fg = kui::Color(0xff, 0xff, 0xff, 0xff);
    theme.border = kui::Color(0x5b, 0x21, 0xb6, 0xff);
    theme.radius = 8.0f;
    return theme;
}

const kui::TooltipTheme g_purple = purple_theme();
kui::TooltipTheme g_default_theme;

void check_tooltip() {
    const double delay = popups().tooltipDelay();
    popups().setTooltipDelay(150.0);
    const double after = popups().tooltipDelay();
    KuiStatus bad_status = status_of([] { popups().setTooltipDelay(-5.0); });
    check("tooltip.delay", near_f(delay, 500.0, 0.01) && near_f(after, 150.0, 0.01) &&
              bad_status == KUI_ERR_INVALID_ARG,
          fmt("default %.1f, after set(150) %.1f, set(-5) status %d", delay, after, bad_status));
    popups().setTooltipDelay(500.0);

    g_default_theme = popups().tooltipTheme();
    popups().setTooltipTheme(g_purple);
    const kui::TooltipTheme theme = popups().tooltipTheme();
    bad_status = status_of([] {
        kui::TooltipTheme bad = g_purple;
        bad.radius = -1.0f;
        popups().setTooltipTheme(bad);
    });
    check("tooltip.theme", themes_equal(theme, g_purple) && bad_status == KUI_ERR_INVALID_ARG,
          fmt("read back %s/%s/%s r%.1f, radius -1 status %d", hex_rgb(theme.bg).c_str(),
              hex_rgb(theme.fg).c_str(), hex_rgb(theme.border).c_str(), theme.radius, bad_status));
    popups().setTooltipTheme(g_default_theme);

    const kui::Rect anchor = rect_of("tip-anchor");
    kui::PopupId id = 0;
    KuiStatus status = status_of([&] {
        id = popups().showTooltip("Tooltip from the host", anchor, kui::PopupPosition::Bottom);
    });
    int shown = has_type(kui::PopupType::Tooltip);
    check("tooltip.show_tooltip", status == KUI_OK && id != 0 && shown == 1 && anchor.width > 0,
          fmt("status %d id %u has tooltip %d anchor %.0fx%.0f", status, id, shown, anchor.width,
              anchor.height));
    bad_status = status_of([&] { popups().showTooltip("x", anchor, static_cast<kui::PopupPosition>(7)); });
    check("tooltip.bad_position", bad_status == KUI_ERR_INVALID_ARG, fmt("status %d", bad_status));
    popups().dismiss(id);
    shown = has_type(kui::PopupType::Tooltip);
    status = status_of([] { popups().dismiss(987654u); });
    check("popup.dismiss_popup", shown == 0 && status == KUI_OK,
          fmt("has tooltip after dismiss %d, unknown id status %d", shown, status));
}

// ---- Context menu: default menu switch, a host menu shown and dismissed by type --------

int g_menu_released = 0;
kui::PopupId g_menu_id = 0;

// Captured by every callback of one menu: destroyed when the Wrapper frees the menu's callbacks
// (from the C release_fn), which is what the C version counts.
struct MenuLifetime {
    ~MenuLifetime() { g_menu_released++; }
};

void on_menu_choice(unsigned item_id) {
    set_text("menu-out", fmt("chose item %u (%s)", item_id,
                             item_id == 1 ? "Red" : item_id == 2 ? "Green" : "?"));
}

// Opens the host menu at #menu-spot's top-left corner: Red, Green, a separator, Disabled.
kui::PopupId show_menu() {
    const kui::Rect spot = rect_of("menu-spot");
    auto lifetime = std::make_shared<MenuLifetime>();
    std::vector<kui::MenuItem> items(4);
    items[0].text = "Red";
    items[0].onClick = [lifetime] { on_menu_choice(1); };
    items[1].text = "Green";
    items[1].onClick = [lifetime] { on_menu_choice(2); };
    items[2].separator = true;
    items[3].text = "Disabled";
    items[3].disabled = true;
    items[3].onClick = [lifetime] { on_menu_choice(3); };
    lifetime.reset();
    return popups().showContextMenu(spot.x, spot.y, std::move(items));
}

void check_menu() {
    kui::EventDispatcher* events = g_doc->eventDispatcher();
    const bool initial = events->isDefaultContextMenuEnabled();
    events->setDefaultContextMenuEnabled(true);
    const bool on = events->isDefaultContextMenuEnabled();
    events->setDefaultContextMenuEnabled(false);
    const bool off = events->isDefaultContextMenuEnabled();
    check("menu.default_enabled", !initial && on && !off,
          fmt("initial %d, after on %d, after off %d", initial, on, off));

    const int released_before = g_menu_released;
    const kui::PopupId id = show_menu();
    int open = has_type(kui::PopupType::ContextMenu);
    check("menu.show_context_menu", id != 0 && open == 1 && g_menu_released == released_before,
          fmt("id %u has menu %d released %d", id, open, g_menu_released));
    // No items: the Wrapper refuses without opening anything (C: KUI_ERR_INVALID_ARG).
    const kui::PopupId empty = popups().showContextMenu(10, 10, {});
    check("menu.no_items", empty == 0 && has_type(kui::PopupType::ContextMenu) == 1,
          fmt("id %u", empty));
    popups().dismissByType(kui::PopupType::ContextMenu);
    open = has_type(kui::PopupType::ContextMenu);
    check("menu.release_fn", open == 0 && g_menu_released == released_before + 1,
          fmt("has menu %d, release calls %d -> %d", open, released_before, g_menu_released));
}

// ---- Popup layer: both kinds at once, removed by type, by id and all at once ------------

kui::PopupId g_tip_id = 0;

void show_both() {
    g_tip_id = popups().showTooltip("Tooltip from the host", rect_of("tip-anchor"),
                                    kui::PopupPosition::Bottom);
    g_menu_id = show_menu();
}

void check_popup_layer() {
    show_both();
    int any = any_popup();
    int tip = has_type(kui::PopupType::Tooltip);
    int menu = has_type(kui::PopupType::ContextMenu);
    const int custom = has_type(kui::PopupType::Custom);
    check("popup.has_popups", any == 1 && tip == 1 && menu == 1 && custom == 0,
          fmt("any %d tooltip %d menu %d custom %d", any, tip, menu, custom));
    popups().dismissByType(kui::PopupType::Tooltip);
    tip = has_type(kui::PopupType::Tooltip);
    menu = has_type(kui::PopupType::ContextMenu);
    check("popup.dismiss_popups_of_type", tip == 0 && menu == 1, fmt("tooltip %d menu %d", tip, menu));
    popups().dismiss(g_menu_id);
    any = any_popup();
    check("popup.dismiss_popup-menu", any == 0, fmt("any %d", any));
    show_both();
    popups().dismissAll();
    any = any_popup();
    const KuiStatus bad_status = status_of([] { popups().dismissByType(static_cast<kui::PopupType>(9)); });
    check("popup.dismiss_all_popups", any == 0 && bad_status == KUI_ERR_INVALID_ARG,
          fmt("any %d, bad type status %d", any, bad_status));
}

// ---- Input pickers: open per input type, page / time / colour, commit and close ---------

int g_time_changes = 0;
int g_time_inputs = 0;

// id of the picker's target input; "" when it is closed (targetInput() is nullptr).
std::string picker_target() {
    kui::HTMLInputElement* target = picker().targetInput();
    return target ? target->id() : std::string();
}

// InputPicker::open* return a bool; this is the direct C call where the exact status matters.
KuiStatus open_status(const char* id, KuiCPickerMode mode) {
    kui::Element* element = by_id(id);
    if (!element) return KUI_ERR_NOT_FOUND;
    return kui_element_open_input_picker(element->cHandle(), mode);
}

void check_picker_date() {
    std::string target = picker_target();
    check("picker.initial_state", !picker().isOpen() && picker().isEnabled() && target.empty(),
          fmt("open %d enabled %d target '%s'", picker().isOpen(), picker().isEnabled(), target.c_str()));

    picker().open(by_id("in-date"));
    target = picker_target();
    kui::Element* panel = g_doc->querySelector("kui-picker");
    check("picker.open_date", picker().isOpen() && picker().mode() == kui::PickerMode::Date &&
              picker().visibleYear() == 2025 && picker().visibleMonth() == 3 && panel != nullptr,
          fmt("open %d mode %s page %d-%d panel %d", picker().isOpen(), mode_name(picker().mode()),
              picker().visibleYear(), picker().visibleMonth(), panel != nullptr));
    check("picker.get_target", target == "in-date", fmt("target '%s'", target.c_str()));

    picker().setVisibleYearMonth(2026, 7);
    const int year = picker().visibleYear();
    const int month = picker().visibleMonth();
    const KuiStatus status = status_of([] { picker().setVisibleYearMonth(2026, 13); });
    check("picker.set_month", year == 2026 && month == 7 && status == KUI_ERR_INVALID_ARG,
          fmt("page %d-%d, month 13 status %d", year, month, status));

    picker().close();
    target = picker_target();
    const std::string value = input_value("in-date");
    check("picker.close", !picker().isOpen() && target.empty() && value == "2025-03-21",
          fmt("open %d target '%s' value '%s'", picker().isOpen(), target.c_str(), value.c_str()));
}

void check_picker_time() {
    picker().openTime(by_id("in-time"));
    check("picker.open_time", picker().isOpen() && picker().mode() == kui::PickerMode::Time &&
              picker().timeHour() == 14 && picker().timeMinute() == 30,
          fmt("open %d mode %s time %d:%d", picker().isOpen(), mode_name(picker().mode()),
              picker().timeHour(), picker().timeMinute()));
    picker().setTime(9, 5);
    const int hour = picker().timeHour();
    const int minute = picker().timeMinute();
    const KuiStatus bad_status = status_of([] { picker().setTime(24, 0); });
    check("picker.set_time", hour == 9 && minute == 5 && bad_status == KUI_ERR_INVALID_ARG,
          fmt("time %d:%d, 24:00 status %d", hour, minute, bad_status));
    picker().commit();
    const std::string value = input_value("in-time");
    check("picker.commit_time", !picker().isOpen() && value == "09:05",
          fmt("open %d value '%s'", picker().isOpen(), value.c_str()));
    check("picker.commit_time-events", g_time_inputs > 0 && g_time_changes > 0,
          fmt("input %d change %d", g_time_inputs, g_time_changes));
}

void check_picker_datetime() {
    picker().open(by_id("in-dtl"));
    check("picker.open_datetime_local", picker().isOpen() &&
              picker().mode() == kui::PickerMode::DateTimeLocal && picker().visibleYear() == 2025 &&
              picker().visibleMonth() == 3,
          fmt("open %d mode %s page %d-%d", picker().isOpen(), mode_name(picker().mode()),
              picker().visibleYear(), picker().visibleMonth()));
    known("picker.open_datetime_local-time", picker().timeHour() == 14 && picker().timeMinute() == 30,
          "the datetime-local panel ignores the input's time and opens at the current time",
          fmt("time %d:%d, value 2025-03-21T14:30", picker().timeHour(), picker().timeMinute()));
    picker().setVisibleYearMonth(2026, 7);
    picker().setTime(8, 15);
    picker().commit();
    const std::string value = input_value("in-dtl");
    check("picker.commit_datetime_local", value == "2026-07-21T08:15", fmt("value '%s'", value.c_str()));
}

void check_picker_color() {
    picker().openColor(by_id("in-color"));
    // #3b82f6 = rgb(59,130,246): h 217.2, s 0.760, v 0.965.
    check("picker.open_color", picker().isOpen() && picker().mode() == kui::PickerMode::Color &&
              near_f(picker().colorH(), 217.2, 1.0) && near_f(picker().colorS(), 0.760, 0.01) &&
              near_f(picker().colorV(), 0.965, 0.01),
          fmt("open %d mode %s hsv %.1f %.3f %.3f (%s)", picker().isOpen(), mode_name(picker().mode()),
              picker().colorH(), picker().colorS(), picker().colorV(), picker().colorHex().c_str()));
    picker().setColorHsv(0.0f, 1.0f, 1.0f);
    const float h = picker().colorH(), s = picker().colorS(), v = picker().colorV();
    const KuiStatus bad_status = status_of([] { picker().setColorHsv(400.0f, 1.0f, 1.0f); });
    check("picker.set_color_hsv", near_f(h, 0, 0.01) && near_f(s, 1, 0.01) && near_f(v, 1, 0.01) &&
              bad_status == KUI_ERR_INVALID_ARG,
          fmt("hsv %.1f %.2f %.2f, h 400 status %d", h, s, v, bad_status));
    picker().commit();
    const std::string value = input_value("in-color");
    check("picker.commit_color", value == "#ff0000", fmt("value '%s'", value.c_str()));
}

void check_picker_refusals() {
    // The Wrapper's open() on an input without a panel / a non-input leaves the picker closed;
    // the C status (gap: open() returns void) tells the two refusals apart.
    picker().open(by_id("in-text"));
    const bool text_open = picker().isOpen();
    picker().open(by_id("not-input"));
    const bool div_open = picker().isOpen();
    const KuiStatus text_status = open_status("in-text", KUI_C_PICKER_NONE);
    const KuiStatus div_status = open_status("not-input", KUI_C_PICKER_NONE);
    check("picker.no_panel", !text_open && !div_open && text_status == KUI_ERR_NOT_SUPPORTED &&
              div_status == KUI_ERR_INVALID_ARG,
          fmt("open after text %d / div %d, text input status %d, div status %d", text_open, div_open,
              text_status, div_status));
    picker().setEnabled(false);
    const bool off_enabled = picker().isEnabled();
    picker().openDate(by_id("in-date"));
    const bool off_open = picker().isOpen();
    const KuiStatus disabled_status = open_status("in-date", KUI_C_PICKER_NONE);
    picker().setEnabled(true);
    const bool on_enabled = picker().isEnabled();
    check("picker.set_enabled", !off_enabled && disabled_status == KUI_ERR_NOT_SUPPORTED && !off_open &&
              on_enabled,
          fmt("disabled %d open status %d open %d, re-enabled %d", !off_enabled, disabled_status,
              off_open, on_enabled));
}

// ---- Final phase: dismissed toasts have finished their exit animation -------------------

void phase_toasts_gone() {
    const int count = toast_count();
    check("toast.count_after_dismiss", count == g_toast_base, fmt("count %d (base %d)", count, g_toast_base));
    finish();
}

// ---- Panel buttons ----------------------------------------------------------------------

kui::u32 g_last_toast = 0;
int g_toast_serial = 0;

void report_toasts(const char* what) { set_text("toast-out", fmt("%s count=%d", what, toast_count())); }

void on_toast_show() {
    g_toast_serial++;
    g_last_toast = show_toast(fmt("Toast #%d from the host", g_toast_serial),
                              static_cast<kui::ToastLevel>(g_toast_serial % 4), 0);
    report_toasts(fmt("shown #%d", g_toast_serial).c_str());
}

void on_toast_dismiss() {
    toasts().dismiss(g_last_toast);
    report_toasts("dismissed last");
}

void on_toast_clear() {
    toasts().dismissAll();
    report_toasts("dismissed all");
}

void on_toast_count() { report_toasts("now"); }

bool g_purple_on = false;
int g_delay_step = 0;

void report_tooltip() {
    const kui::TooltipTheme theme = popups().tooltipTheme();
    set_text("tip-out", fmt("theme=%s bg=#%s delay=%.0f tooltip=%d", g_purple_on ? "purple" : "default",
                            hex_rgb(theme.bg).c_str(), popups().tooltipDelay(),
                            has_type(kui::PopupType::Tooltip)));
}

void on_tip_show() {
    g_tip_id = popups().showTooltip("Tooltip from the host", rect_of("tip-anchor"),
                                    kui::PopupPosition::Bottom);
    report_tooltip();
}

void on_tip_hide() {
    popups().dismiss(g_tip_id);
    report_tooltip();
}

void on_tip_theme() {
    g_purple_on = !g_purple_on;
    popups().setTooltipTheme(g_purple_on ? g_purple : g_default_theme);
    on_tip_show();   // the click closed the tooltip: show it again in the new colours
}

void on_tip_delay() {
    static const double delays[3] = {500.0, 150.0, 1000.0};
    g_delay_step = (g_delay_step + 1) % 3;
    popups().setTooltipDelay(delays[g_delay_step]);
    report_tooltip();
}

void on_menu_show() {
    g_menu_id = show_menu();
    set_text("menu-out", fmt("menu open=%d", has_type(kui::PopupType::ContextMenu)));
}

void on_menu_default() {
    kui::EventDispatcher* events = g_doc->eventDispatcher();
    events->setDefaultContextMenuEnabled(!events->isDefaultContextMenuEnabled());
    set_text("menu-out", events->isDefaultContextMenuEnabled() ? "default=on" : "default=off");
}

bool g_context_custom = false;

void report_context_menu() {
    set_text("menu-out", fmt("contextmenu: %s menu open=%d", g_context_custom ? "custom" : "default",
                             has_type(kui::PopupType::ContextMenu)));
}

// Right-click: the built-in menu when it is enabled, the host's own menu otherwise.
void on_context_menu(kui::Event& event) {
    const bool enabled = g_doc->eventDispatcher()->isDefaultContextMenuEnabled();
    g_context_custom = !enabled;
    if (!enabled) {
        event.preventDefault();
        g_menu_id = show_menu();
    }
    kui::Platform::setTimeout([] { report_context_menu(); }, 100);
}

// A click anywhere dismisses open popups first, so each button shows both kinds again and then
// applies its own removal; the report is "before -> after".
std::string popup_counts() {
    return fmt("popups=%d tooltip=%d menu=%d", any_popup(), has_type(kui::PopupType::Tooltip),
               has_type(kui::PopupType::ContextMenu));
}

void report_popups(const std::string& before) {
    set_text("pop-out", before.empty() ? popup_counts() : before + " -> " + popup_counts());
}

void on_pop_both() {
    show_both();
    report_popups("");
}

void on_pop_tip_off() {
    show_both();
    const std::string before = popup_counts();
    popups().dismissByType(kui::PopupType::Tooltip);
    report_popups(before);
}

void on_pop_menu_id() {
    show_both();
    const std::string before = popup_counts();
    popups().dismiss(g_menu_id);
    report_popups(before);
}

void on_pop_clear() {
    show_both();
    const std::string before = popup_counts();
    popups().dismissAll();
    report_popups(before);
}

void report_picker(const std::string& what) {
    const std::string target = picker_target();
    set_text("pick-out", what + fmt("open=%d enabled=%d mode=%s page=%04d-%02d target=%s",
                                    picker().isOpen(), picker().isEnabled(), mode_name(picker().mode()),
                                    picker().visibleYear(), picker().visibleMonth(),
                                    target.empty() ? "-" : target.c_str()));
}

void report_values() {
    set_text("pick-values", "time=" + input_value("in-time") + " dtl=" + input_value("in-dtl") +
                                " color=" + input_value("in-color"));
}

void on_pick_date() {
    const KuiStatus status = open_status("in-date", KUI_C_PICKER_NONE);   // the status is shown
    report_picker(fmt("status=%s ", status_name(status)));
}

void on_pick_close() {
    picker().close();
    report_picker("");
}

void on_pick_time() {
    picker().openTime(by_id("in-time"));
    if (picker().isOpen()) {
        picker().setTime(18, 45);
        picker().commit();
    }
    report_picker("");
    report_values();
}

void on_pick_dtl() {
    picker().openDateTimeLocal(by_id("in-dtl"));
    if (picker().isOpen()) {
        picker().setVisibleYearMonth(2027, 1);
        picker().setTime(22, 10);
        picker().commit();
    }
    report_picker("");
    report_values();
}

void on_pick_color() {
    picker().openColor(by_id("in-color"));
    if (picker().isOpen()) {
        picker().setColorHsv(120.0f, 1.0f, 1.0f);
        picker().commit();
    }
    report_picker("");
    report_values();
}

void on_pick_toggle() {
    picker().setEnabled(!picker().isEnabled());
    const KuiStatus status = open_status("in-date", KUI_C_PICKER_NONE);   // the status is shown
    if (status == KUI_OK) picker().close();
    report_picker(fmt("open(date) status=%s ", status_name(status)));
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = by_id(id);
    if (!button) {
        check(std::string("ui.") + id, false, "button missing");
        return;
    }
    button->addEventListener("click", [handler, id](kui::Event&) {
        try {
            handler();
        } catch (const std::exception& error) {
            std::fprintf(stderr, "%s: %s\n", id, error.what());
        }
    });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    (void)window;
    g_doc = &document;
    // Overlay popups (the default; the C runner sets it the same way).
    popups().setPopupMode(kui::PopupMode::Overlay);

    if (kui::Element* time = by_id("in-time")) {
        time->addEventListener("change", [](kui::Event&) { g_time_changes++; });
        time->addEventListener("input", [](kui::Event&) { g_time_inputs++; });
    }

    run_group("toast", check_toasts);
    run_group("tooltip", check_tooltip);
    run_group("menu", check_menu);
    run_group("popup", check_popup_layer);
    run_group("picker", check_picker_date);
    run_group("picker", check_picker_time);
    run_group("picker", check_picker_datetime);
    run_group("picker", check_picker_color);
    run_group("picker", check_picker_refusals);
    run_group("picker", report_values);
    // Toast exit animations take a few hundred milliseconds.
    kui::Platform::setTimeout([] { run_group("toast", phase_toasts_gone); }, 1200);

    on_click("btn-toast-show", on_toast_show);
    on_click("btn-toast-dismiss", on_toast_dismiss);
    on_click("btn-toast-clear", on_toast_clear);
    on_click("btn-toast-count", on_toast_count);
    on_click("btn-tip-show", on_tip_show);
    on_click("btn-tip-hide", on_tip_hide);
    on_click("btn-tip-theme", on_tip_theme);
    on_click("btn-tip-delay", on_tip_delay);
    on_click("btn-menu-show", on_menu_show);
    on_click("btn-menu-default", on_menu_default);
    if (kui::Element* spot = by_id("menu-spot")) {
        spot->addEventListener("contextmenu", [](kui::Event& event) {
            try {
                on_context_menu(event);
            } catch (const std::exception& error) {
                std::fprintf(stderr, "menu-spot: %s\n", error.what());
            }
        });
    }
    on_click("btn-pop-both", on_pop_both);
    on_click("btn-pop-tip-off", on_pop_tip_off);
    on_click("btn-pop-menu-id", on_pop_menu_id);
    on_click("btn-pop-clear", on_pop_clear);
    on_click("btn-pick-date", on_pick_date);
    on_click("btn-pick-close", on_pick_close);
    on_click("btn-pick-time", on_pick_time);
    on_click("btn-pick-dtl", on_pick_dtl);
    on_click("btn-pick-color", on_pick_color);
    on_click("btn-pick-toggle", on_pick_toggle);
}
// ---- end of examples/api_tours/popups_input/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 popups, toasts & input pickers";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_popups_input] %s\n", error.what());
        return 9;
    }
}
